<body>

  <div class="header">
    <h1>Frontier AI Models Compared: Intelligence, Speed & Cost</h1>
    <p>A data-driven comparison of the top 10 frontier AI language models across intelligence, output speed, and pricing based on the Artificial Analysis Intelligence Index v4.0.</p>
  </div>

  <div class="hero-stats">
    <div class="stat-card">
      <h3>Peak Intelligence</h3>
      <div class="value">57 <span style="font-size: 40px; color:#6b7280; font-weight: 600;">Score</span></div>
      <div class="desc">Gemini 3.1 Pro & GPT-5.4 tie</div>
    </div>
    <div class="stat-card">
      <h3>Fastest Output</h3>
      <div class="value">206 <span style="font-size: 40px; color:#6b7280; font-weight: 600;">tok/s</span></div>
      <div class="desc">gpt-oss-120B leads in speed</div>
    </div>
    <div class="stat-card">
      <h3>Price Range</h3>
      <div class="value">33&times; <span style="font-size: 40px; color:#6b7280; font-weight: 600;">gap</span></div>
      <div class="desc">From $0.30 to $10.00 / 1M tokens</div>
    </div>
  </div>

  <div class="hero-chart">
    <h2>The Intelligence–Speed–Cost Trade-Off</h2>
    <p class="subtitle">Bubble size represents <strong>Cost</strong> per 1M tokens ($0.30 to $10.00). The ideal model is top-right (Smart & Fast) with a small bubble (Cheap).</p>

    <div class="scatter-container">
      <div class="y-axis-label">INTELLIGENCE SCORE &rarr;</div>
      <div class="x-axis-label">OUTPUT SPEED (tokens/sec) &rarr;</div>

      <div id="scatter-plot"></div>

      <div class="axis-val" style="bottom: -40px; left: 0;">0 tok/s</div>
      <div class="axis-val" style="bottom: -40px; right: 0;">220 tok/s</div>
      <div class="axis-val" style="left: -50px; bottom: 0;">30</div>
      <div class="axis-val" style="left: -50px; top: 0;">60</div>
    </div>
  </div>

  <div class="lower-sections">
    <div class="chart-box">
      <div id="intel-chart" class="infographic-container"></div>
    </div>
    <div class="chart-box">
      <div id="speed-chart" class="infographic-container"></div>
    </div>
    <div class="chart-box">
      <div id="cost-chart" class="infographic-container"></div>
    </div>
  </div>

  <div class="footer">
    <p><strong>About the Index:</strong> The Artificial Analysis Intelligence Index v4.0 incorporates 10 independent evaluations spanning coding, agentic tasks, scientific reasoning, knowledge accuracy, and instruction following.</p>
  </div>

  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const models = [
      { name: "Gemini 3.1 Pro", intel: 57, speed: 129, cost: 4.50, color: "#06b6d4" },
      { name: "GPT-5.4", intel: 57, speed: 72, cost: 5.60, color: "#3b82f6" },
      { name: "Claude Opus 4.6", intel: 53, speed: 40, cost: 10.00, color: "#8b5cf6" },
      { name: "Claude Sonnet 4.6", intel: 52, speed: 48, cost: 6.00, color: "#d946ef" },
      { name: "GLM-5.1", intel: 51, speed: 40, cost: 2.10, color: "#ec4899" },
      { name: "Grok 4.20 v2", intel: 49, speed: 162, cost: 3.00, color: "#f43f5e" },
      { name: "Gemini 3 Flash", intel: 46, speed: 149, cost: 1.10, color: "#f59e0b" },
      { name: "DeepSeek V3.2", intel: 42, speed: 31, cost: 0.30, color: "#10b981" },
      { name: "Nemotron 3", intel: 36, speed: 193, cost: 0.40, color: "#84cc16" },
      { name: "gpt-oss-120B", intel: 33, speed: 206, cost: 0.30, color: "#22c55e" }
    ];

    const plot = document.getElementById('scatter-plot');
    models.forEach(m => {
      const xPercent = (m.speed / 220) * 100;
      const yPercent = ((m.intel - 30) / 30) * 100;

      const size = 40 + Math.sqrt(m.cost) * 25; 

      const dot = document.createElement('div');
      dot.className = 'dot';
      dot.style.left = xPercent + '%';
      dot.style.bottom = yPercent + '%';
      dot.style.width = size + 'px';
      dot.style.height = size + 'px';
      dot.style.backgroundColor = m.color + 'bb';
      dot.style.borderColor = m.color;

      const label = document.createElement('div');
      label.className = 'dot-label';
      label.innerText = m.name;

      if(yPercent > 85) {
        label.style.top = 'auto';
        label.style.bottom = '-60px';
      }

      dot.appendChild(label);
      plot.appendChild(dot);
    });

    const intelDsl = `infographic chart-bar-plain-text
data
  title Intelligence Score
  values
    - label Gemini 3.1 Pro
      value 57
    - label GPT-5.4
      value 57
    - label Claude Opus 4.6
      value 53
    - label Muse Spark
      value 52
    - label Claude Sonnet 4.6
      value 52
    - label GLM-5.1
      value 51
    - label Grok 4.20
      value 49
    - label Gemini 3 Flash
      value 46
    - label DeepSeek V3.2
      value 42
    - label Nemotron 3
      value 36
    - label gpt-oss-120B
      value 33
theme
  palette #06b6d4`;

    const speedDsl = `infographic chart-bar-plain-text
data
  title Output Speed (tok/s)
  values
    - label gpt-oss-120B
      value 206
    - label Nemotron 3
      value 193
    - label Grok 4.20
      value 162
    - label Gemini 3 Flash
      value 149
    - label Gemini 3.1 Pro
      value 129
    - label GPT-5.4
      value 72
    - label Claude Sonnet 4.6
      value 48
    - label GLM-5.1
      value 40
    - label Claude Opus 4.6
      value 40
    - label DeepSeek V3.2
      value 31
theme
  palette #f59e0b`;

    const costDsl = `infographic chart-bar-plain-text
data
  title Cost ($/1M tokens)
  values
    - label Claude Opus 4.6
      value 10.00
    - label Claude Sonnet 4.6
      value 6.00
    - label GPT-5.4
      value 5.60
    - label Gemini 3.1 Pro
      value 4.50
    - label Grok 4.20
      value 3.00
    - label GLM-5.1
      value 2.10
    - label Gemini 3 Flash
      value 1.10
    - label Nemotron 3
      value 0.40
    - label DeepSeek V3.2
      value 0.30
    - label gpt-oss-120B
      value 0.30
theme
  palette #10b981`;

    const igIntel = new AntVInfographic.Infographic({ container: '#intel-chart', width: '100%', height: '100%' });
    const igSpeed = new AntVInfographic.Infographic({ container: '#speed-chart', width: '100%', height: '100%' });
    const igCost = new AntVInfographic.Infographic({ container: '#cost-chart', width: '100%', height: '100%' });

    // Attempt rendering, also re-render when fonts are loaded
    const renderAll = () => {
      try { igIntel.render(intelDsl); } catch(e){}
      try { igSpeed.render(speedDsl); } catch(e){}
      try { igCost.render(costDsl); } catch(e){}
    };

    renderAll();

    document.fonts?.ready.then(() => {
      renderAll();
      setTimeout(() => {
        document.body.setAttribute('data-render-done', 'true');
      }, 1500);
    }).catch(() => {
      setTimeout(() => {
        document.body.setAttribute('data-render-done', 'true');
      }, 1500);
    });
  </script>
</body>
</html>
